 $today=(new DateTimeImmutable('today',new DateTimeZone('Asia/Ho_Chi_Minh')))->setTimezone(new DateTimeZone('UTC'))->format('Y-m-d\TH:i:s\Z');$stats=$db->prepare("SELECT count(*) AS all_count, SUM(CASE WHEN created_at>=? THEN 1 ELSE 0 END) AS today, SUM(CASE WHEN status IN ('pending_confirmation','pending_quote') THEN 1 ELSE 0 END) AS pending, SUM(CASE WHEN status='completed' THEN COALESCE(json_extract(payload,'$.total'),0) ELSE 0 END) AS completed_value FROM orders WHERE NOT EXISTS(SELECT 1 FROM order_admin_trash t WHERE t.code=orders.code)");$stats->execute([$today]);api_reply(['orders'=>$orders,'total'=>$total,'page'=>$page,'pages'=>$pages,'stats'=>$stats->fetch()]);
